(()=>{'use strict';const $=(s,c=document)=>c.querySelector(s),$$=(s,c=document)=>[...c.querySelectorAll(s)];
function editFilter(kind='all'){const grid=$('[data-edit-grid]');if(!grid)return;let count=0;$$('.product-card',grid).forEach(card=>{const match=kind==='all'||card.dataset.kind===kind;card.hidden=!match||count>=4;if(match)count++});grid.dataset.filterActive=kind;$$('[data-edit-filter]').forEach(b=>{b.classList.toggle('active',b.dataset.editFilter===kind);b.setAttribute('aria-pressed',String(b.dataset.editFilter===kind))})}
document.addEventListener('click',e=>{const filter=e.target.closest('[data-edit-filter]');if(filter)editFilter(filter.dataset.editFilter);const category=e.target.closest('[data-category-link]');if(category&&!window.Essaint?.preview){e.preventDefault();location.href=(window.Essaint?.root||'/')+'collections/all?essaint_category='+encodeURIComponent(category.dataset.categoryLink)}});editFilter();
const collectionKind=new URLSearchParams(location.search).get('essaint_category');if(collectionKind&&!window.Essaint?.preview){$$('.collection .product-card').forEach(p=>p.hidden=p.dataset.kind!==collectionKind)}
function initStudio(container){if(container.dataset.ready)return;container.dataset.ready='true';const U=window.EssaintUI,parts=['top','bottom'],state={},revision={top:0,bottom:0},form=$('form',container),add=$('[data-studio-add]',container),message=$('[data-studio-message]',container),total=$('[data-studio-total]',container);
const selected=part=>{const v=$(`[data-studio-variant="${part}"]`,container);return state[part]?.variants.find(x=>String(x.id)===v.value)};
function update(){const variants=parts.map(selected);const valid=variants.every(v=>v?.available);add.disabled=!valid;total.textContent=valid?U.money(variants.reduce((sum,v)=>sum+v.price,0)):'—';if(valid)message.textContent='Two pieces, selected by you. Eligible discounts apply at checkout.'}
async function load(part){const rev=++revision[part],handle=$(`[data-studio-product="${part}"]`,container).value,vSelect=$(`[data-studio-variant="${part}"]`,container);delete state[part];add.disabled=true;vSelect.disabled=true;vSelect.innerHTML='<option>Loading available options…</option>';total.textContent='—';try{if(!handle)throw Error('Choose products for this set in the theme editor.');const p=await U.product(handle);if(rev!==revision[part])return;state[part]=p;const v=p.variants.find(v=>v.available);vSelect.innerHTML=p.variants.map(x=>`<option value="${x.id}" ${x.available?'':'disabled'} ${x.id===v?.id?'selected':''}>${U.esc(x.title)}${x.available?'':' — Sold out'}</option>`).join('');vSelect.disabled=!v;const img=$(`[data-studio-image="${part}"]`,container);img.src=p.featured_image;img.alt=p.title;if(!v)message.textContent='This piece is sold out. Choose another style.';update()}catch(e){if(rev!==revision[part])return;vSelect.innerHTML='<option>Options unavailable</option>';message.textContent=e.message;update()}}
parts.forEach(part=>{$(`[data-studio-product="${part}"]`,container).addEventListener('change',()=>load(part));$(`[data-studio-variant="${part}"]`,container).addEventListener('change',update)});
form.addEventListener('submit',async e=>{e.preventDefault();const variants=parts.map(selected);if(!variants.every(v=>v?.available))return;await U.addItems(variants.map(v=>({id:v.id,quantity:1,properties:{'Outfit edit':'Your uniform'}})),add);update()});
$$('[data-studio-preset]').forEach(b=>b.addEventListener('click',async()=>{const handles=b.dataset.studioPreset.split(',');parts.forEach((part,i)=>{const selector=$(`[data-studio-product="${part}"]`,container);if([...selector.options].some(o=>o.value===handles[i]))selector.value=handles[i]});await Promise.all(parts.map(load));form.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'center'})}));Promise.all(parts.map(load));}
$$('[data-studio]').forEach(initStudio);document.addEventListener('shopify:section:load',e=>{if($('[data-studio]',e.target))initStudio($('[data-studio]',e.target));editFilter()});
})();
